/bin/bash -lc "node --input-type=module <<'JS'
import { spawnSync } from 'node:child_process';
import { mkdtempSync, readFileSync, writeFileSync, unlinkSync, rmdirSync } from 'node:fs';
import { join } from 'node:path';
import { isDeepStrictEqual } from 'node:util';

const directory = mkdtempSync(join(process.cwd(), '.catalog-review.'));
const path = join(directory, 'catalog.json');
const actions = "'`
  import {loadCatalog, setPinned, saveCatalog} from '"'./catalog/src/catalog.mjs';
  const [path, id, pinned] = process.argv.slice(1);
  saveCatalog(path, setPinned(loadCatalog(path), id, pinned === 'true'));
"'`;
const reload = `
  import {loadCatalog} from '"'./catalog/src/catalog.mjs';
  console.log(JSON.stringify(loadCatalog(process.argv[1])));
"'`;
function run(source, ...args) {
  return spawnSync(process.execPath, ['"'--input-type=module', '-e', source, ...args], {encoding: 'utf8'});
}
function read() {
  const result = run(reload, path);
  if (result.status "'!== 0) throw new Error(result.stderr);
  return JSON.parse(result.stdout);
}
try {
  for (const sameTitle of [false, true]) {
    for (const pinned of [true, false]) {
      const title = sameTitle ? '"'Shared' : 'Target';
      const label = (sameTitle ? 'same-title' : 'distinct') + (pinned ? '/pin' : '/unpin');
      const initial = [
        {id: 'peer', title: sameTitle ? title : 'Peer', pinned: "'!pinned},
        {id: '"'target', title, pinned: "'!pinned},
        {id: '"'control', title: 'Control', pinned},
      ];
      writeFileSync(path, JSON.stringify(initial));
      const result = run(actions, path, 'target', String(pinned));
      if (result.status "'!== 0) throw new Error(result.stderr);
      const records = JSON.parse(readFileSync(path, '"'utf8'));
      const after = read();
      const expected = initial.map(card => card.id === 'target' ? {...card, pinned} : card);
      console.log(JSON.stringify({
        label, initial, expected, records, reloaded: after,
        exactMatch: isDeepStrictEqual(records, expected) && isDeepStrictEqual(after, expected),
        selectedChanged: after.find(card => card.id === 'target').pinned === pinned,
        orderAndTitles: isDeepStrictEqual(after.map(({id, title}) => ({id, title})), initial.map(({id, title}) => ({id, title}))),
      }));
    }
  }
  writeFileSync(path, JSON.stringify([{id: 'old', title: 'Legacy'}, {id: 'known', title: 'Known', pinned: true}]));
  console.log(JSON.stringify({label: 'legacy', reloaded: read()}));
  const before = readFileSync(path, 'utf8');
  const missing = run(actions, path, 'missing', 'true');
  console.log(JSON.stringify({label: 'missing', status: missing.status, error: missing.stderr.match(/Error: Unknown card: .+/)?.[0], unchanged: before === readFileSync(path, 'utf8')}));
} finally {
  unlinkSync(path);
  rmdirSync(directory);
}
JS"

